import java.util.HashMap;
import java.util.Map;

Map result = new HashMap();
String empNo = (account == null) ? null : account.getStringAttribute("employeeNumber");

if (empNo != null && empNo.trim().length() > 0) {
    result.put("identityAttributeName", "employeeNumber");
    result.put("identityAttributeValue", empNo.trim());
}
return result;
